rows = [{"source": "A", "value": 180, "unit": "s"},
        {"source": "B", "value": 4, "unit": "min"}]
minutes = []
for row in rows:
    if row["unit"] == "s":
        minutes.append(row["value"] / 60)
    elif row["unit"] == "min":
        minutes.append(row["value"])
    else:
        minutes.append(None)
print(minutes)
